from __future__ import annotations

import numpy as np

from f3.sectors.e4a_common import E4ASector, exp, ifelse, log, pulse, ramp, step, withlookup  # noqa: F401

PARAMS = {
    "TEGR": 4.0,
    "INELOK": -0.5,
    "NK": 0.3,
    "I_PGDPP": 5.952000000000001,
}
PARAMS_GL = {}
PARAM_EXPR = {
}
INITS = {
    "PGDPP": 5.952000000000001,
}
STATE_NAMES = ("PGDPP", )
STATE_INIT = {
    "PGDPP": 'I["PGDPP"]',
}
INPUT_NAMES = ("CE", "COFO", "GDPP", "INEQ", "POP", )
UNITS = {
    "CE": "gusd/y",
    "CFETA": "gusd/y",
    "COFO": "gusd/y",
    "CTA": "gusd/y",
    "FB15": "1",
    "GDPP": "kusd/p/y",
    "IEL": "1",
    "INEQ": "1",
    "LK": "1",
    "PB15": "mp",
    "PGDPP": "kusd/y",
    "POP": "mp",
    "RGGDPP": "1/y",
}

# algebraic equations (name: expression of the other variables; L = line in subsystems.jl)
EQ = {
    "CFETA": lambda v: v.COFO + v.CE,  # L29
    "CTA": lambda v: v.CFETA,  # L30
    "FB15": lambda v: 1 - (1 / (1 + exp(-v.LK * (v.GDPP - 14)))),  # L31
    "IEL": lambda v: 1 + v.INELOK * (v.INEQ / 0.5 - 1),  # L32
    "LK": lambda v: v.NK * v.IEL,  # L33
    "PB15": lambda v: v.POP * v.FB15,  # L34
    "RGGDPP": lambda v: ((v.GDPP - v.PGDPP) / v.PGDPP) / v.TEGR,  # L35
}

# derivatives of the states (smooth!(x, input, T) is D(x) = (input - x) / T)
DER = {
    "PGDPP": lambda v: (v.GDPP - v.PGDPP) / (v.TEGR),  # L36
}


class OtherSector(E4ASector):
    name = "e4a_other"
    SECTOR_KEY = "other"
    STATE_NAMES = STATE_NAMES
    PARAMS = PARAMS
    PARAMS_GL = PARAMS_GL
    PARAM_EXPR = PARAM_EXPR
    INITS = INITS
    STATE_INIT = STATE_INIT
    EQ = EQ
    DER = DER
    INPUT_NAMES = INPUT_NAMES
    inputs = {n: UNITS[n] for n in INPUT_NAMES}
    outputs = {n: UNITS[n] for n in list(EQ) + list(STATE_NAMES)}


SECTOR_CLASS = OtherSector
